require_once __DIR__ . '/../includes/auth.php';$u=require_role(['superadmin']);$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=$_POST['current_password'];$new=$_POST['new_password'];$s=$pdo->prepare("SELECT password_hash FROM accounts WHERE id=?");$s->execute([$u['id']]);$hash=$s->fetchColumn();if(!password_verify($current,$hash))$error='Current password is incorrect.';elseif(strlen($new)<8)$error='New password must contain at least 8 characters.';else{$pdo->prepare("UPDATE accounts SET password_hash=?,must_change_password=0 WHERE id=?")->execute([password_hash($new,PASSWORD_DEFAULT),$u['id']]);$_SESSION['account']['must_change_password']=0;log_audit($pdo,'PASSWORD_CHANGE','account',$u['id'],'Super administrator changed password');$success='Password changed successfully.';}}
page_header('Account Settings');?><h1>Change Super Administrator Password</h1><?php if(isset($_GET['first'])):?><div class="notice">You are using the initial password. Change it before continuing.</div><?php endif;?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><div class="panel"><div class="panel-body"><form method="post"><?=csrf_field()?><div class="field"><label>Current Password</label><input type="password" name="current_password" required></div><div class="field"><label>New Password (at least 8 characters)</label><input type="password" name="new_password" minlength="8" required></div><button>Update Password</button></form></div></div><p class="muted">For a local classroom demonstration only, contact your project administrator if the super administrator password is lost. Do not use a public hardcoded secret-word bypass in a real deployment.</p><?php page_footer();?>
